/* auto_fixture_v2.h - frozen automation records with phase C's ignorable fields, still format
 * compat 1 (docs/features/41 DESIGN.md section 6 "Stored format", AUT-008, AUT-014, D29, D30).
 *
 * Never edit; a later format change adds auto_fixture_v3.h. Written by hand, never generated by
 * the encoder. auto_fixture_v1.h stays as it is and still reads the same.
 *
 * The ignorable fields phase C knows (ids 0x80 and above: an older firmware keeps them as stored
 * and runs the rule without them):
 *   0x82  u8   bit n = action n+1's "Bypass open zones" (only on an Arm action). Without it an
 *              older firmware arms without bypassing: it fails on an open zone, never arms less
 *              protected.
 *   0x83  u32  changed_at, epoch seconds LE: when the sentence last changed. Without it an
 *              older firmware shows no "changed since": words only.
 */
#ifndef AUTO_FIXTURE_V2_H
#define AUTO_FIXTURE_V2_H

#include <stdint.h>

/* (k) 22:30 every day -> Arm Night on partition 1, 5 minutes' warning, made by user 2, with
 * "Bypass open zones", its sentence changed at 1,800,000,000 (2027-01-15 08:00 UTC). uid 11. */
static const uint8_t AUTO_FX_K[] = {
    0x01,                         /* compat 1 */
    0x01, 0x02, 0x0B, 0x00,       /* uid 11 */
    0x04, 0x01, 0x02,             /* made_by user 2 */
    0x10, 0x01, 0x07,             /* trigger: time */
    0x14, 0x02, 0x46, 0x05,       /* minute 1350 (22:30) */
    0x20, 0x01, 0x02,             /* action 1: arm */
    0x2A, 0x01, 0x01,             /* partition 1 */
    0x2B, 0x01, 0x03,             /* Night */
    0x2C, 0x01, 0x05,             /* 5 minutes */
    0x82, 0x01, 0x01,             /* bypass: action 1 */
    0x83, 0x04, 0x00, 0xD2, 0x49, 0x6B, /* changed_at 1800000000 = 0x6B49D200 */
};

/* (l) The same rule as an older firmware without those fields sees it: its ids renumbered to
 * ignorable ids no firmware knows (0x92, 0x93), so this one reads them as an older one does. */
static const uint8_t AUTO_FX_L[] = {
    0x01,
    0x01, 0x02, 0x0B, 0x00,
    0x04, 0x01, 0x02,
    0x10, 0x01, 0x07,
    0x14, 0x02, 0x46, 0x05,
    0x20, 0x01, 0x02,
    0x2A, 0x01, 0x01,
    0x2B, 0x01, 0x03,
    0x2C, 0x01, 0x05,
    0x92, 0x01, 0x01,             /* unknown, ignorable */
    0x93, 0x04, 0x00, 0xD2, 0x49, 0x6B, /* unknown, ignorable */
};

/* (m) A bypass bit on a device action (an older firmware kept 0x82 through an edit that turned
 * the Arm into Turn off light.hall): the bit means nothing and is dropped; the rule is OK. And a
 * changed_at of the wrong length, kept as stored like an unknown field. uid 13. */
static const uint8_t AUTO_FX_M[] = {
    0x01,
    0x01, 0x02, 0x0D, 0x00,       /* uid 13 */
    0x10, 0x01, 0x02,             /* trigger: disarmed */
    0x20, 0x01, 0x01,             /* device */
    0x21, 0x01, 0x01,             /* Home Assistant */
    0x22, 0x01, 0x01,             /* light */
    0x23, 0x01, 0x02,             /* off */
    0x26, 0x0A, 'l', 'i', 'g', 'h', 't', '.', 'h', 'a', 'l', 'l',
    0x82, 0x01, 0x01,             /* bypass on a device action: dropped */
    0x83, 0x02, 0x34, 0x12,       /* changed_at, 2 bytes: kept as stored */
};

#endif /* AUTO_FIXTURE_V2_H */
